std::mutex g_runtimeRegistryMutex;
std::unordered_set<ExactHermesRuntime*> g_activeRuntimes;

void registerRuntime(ExactHermesRuntime* runtime) {
  if (!runtime) return;
  std::lock_guard<std::mutex> lock(g_runtimeRegistryMutex);
  g_activeRuntimes.insert(runtime);
}

void unregisterRuntime(ExactHermesRuntime* runtime) {
  if (!runtime) return;
  std::lock_guard<std::mutex> lock(g_runtimeRegistryMutex);
  g_activeRuntimes.erase(runtime);
}

bool runtimeIsAlive(ExactHermesRuntime* runtime) {
  if (!runtime) return false;
  std::lock_guard<std::mutex> lock(g_runtimeRegistryMutex);
  return g_activeRuntimes.find(runtime) != g_activeRuntimes.end();
}

constexpr uint32_t EXACT_FETCH_TIMEOUT_MS = 30000;

bool hasPendingFetchCallbacks(ExactHermesRuntime* runtime) {
  if (!runtime) {
    return false;
  }

  std::lock_guard<std::mutex> lock(runtime->fetchMutex);
  return !runtime->fetchCallbacks.empty();
}

void cleanupFetchCallbacks(ExactHermesRuntime* runtime) {
  if (!runtime || !runtime->runtime) {
    return;
  }

  auto now = std::chrono::steady_clock::now();
  std::vector<std::pair<std::shared_ptr<facebook::jsi::Function>, std::string>> expired;

  {
    std::lock_guard<std::mutex> lock(runtime->fetchMutex);
    for (auto it = runtime->fetchCallbacks.begin();
         it != runtime->fetchCallbacks.end();) {
      if (it->second.deadline <= now) {
        expired.push_back({
            std::move(it->second.reject),
            std::move(it->second.url),
        });
        it = runtime->fetchCallbacks.erase(it);
      } else {
        ++it;
      }
    }
  }

  for (auto& entry : expired) {
    auto& reject = entry.first;
    auto& url = entry.second;
    if (!reject) {
      continue;
    }
    try {
      reject->call(*runtime->runtime,
                   facebook::jsi::JSError(*runtime->runtime,
                                          ("Fetch timeout: " + url).c_str())
                       .value());
    } catch (...) {
    }
  }
}

struct NativeWebSocketCallbackContext {
  ExactHermesRuntime* runtime;
  std::shared_ptr<facebook::jsi::Object> ws_instance;
  std::atomic<uint32_t> ref_count{1};
};

extern "C" void native_ws_retain_context(void* context) {
  auto* ctx = static_cast<NativeWebSocketCallbackContext*>(context);
  if (!ctx) {
    return;
  }
  ctx->ref_count.fetch_add(1, std::memory_order_relaxed);
}

extern "C" void native_ws_release_context(void* context) {
  auto* ctx = static_cast<NativeWebSocketCallbackContext*>(context);
  if (!ctx) {
    return;
  }
  if (ctx->ref_count.fetch_sub(1, std::memory_order_acq_rel) == 1) {
    delete ctx;
  }
}

struct CFUniqueReleaser {
  void operator()(const void* ptr) const {
    if (ptr) {
#if defined(__APPLE__)
      CFRelease(ptr);
#endif
    }
  }
};

using CFUniquePtr = std::unique_ptr<const void, CFUniqueReleaser>;

template <typename T>
using CFRefPtr = std::unique_ptr<std::remove_pointer_t<T>, CFUniqueReleaser>;

template <typename T>
CFRefPtr<T> adoptCF(T ptr) {
  return CFRefPtr<T>(ptr);
}

class VectorBuffer : public facebook::jsi::MutableBuffer {
 public:
  explicit VectorBuffer(std::vector<uint8_t> data) : data_(std::move(data)) {}

  size_t size() const override { return data_.size(); }
  uint8_t* data() override { return data_.data(); }

 private:
  std::vector<uint8_t> data_;
};

extern "C" void ex_hermes_notify_callback();

void pushRuntimeCallback(ExactHermesRuntime* runtime,
                          std::function<void(facebook::jsi::Runtime&)> fn) {
    if (!runtimeIsAlive(runtime)) return;
    std::lock_guard<std::mutex> lock(runtime->callbackMutex);
    runtime->callbackQueue.push_back(std::move(fn));
    ex_hermes_notify_callback();
}

int drainCallbackQueue(ExactHermesRuntime* runtime) {
    std::deque<std::function<void(facebook::jsi::Runtime&)>> queue;
    {
        std::lock_guard<std::mutex> lock(runtime->callbackMutex);
        queue.swap(runtime->callbackQueue);
    }
    int count = 0;
    for (auto& fn : queue) {
        try {
            fn(*runtime->runtime);
            count++;
        } catch (const facebook::jsi::JSError& err) {
            ex_host_console_log(1, err.getMessage().c_str());
        } catch (...) {
            ex_host_console_log(1, "Callback execution failed");
        }
    }
    return count;
}

void emitScriptParsed(ExactHermesRuntime* runtime,
                      const facebook::hermes::debugger::SourceLocation& loc) {
  using facebook::hermes::debugger::kInvalidLocation;
  uint32_t line = loc.line == kInvalidLocation ? 0 : (loc.line > 0 ? loc.line - 1 : 0);
  uint32_t column = loc.column == kInvalidLocation ? 0 : (loc.column > 0 ? loc.column - 1 : 0);

  std::ostringstream out;
  out << "{\"method\":\"Debugger.scriptParsed\",\"params\":{";
  out << "\"scriptId\":" << jsonString(std::to_string(loc.fileId)) << ",";
  out << "\"url\":" << jsonString(loc.fileName) << ",";
  out << "\"startLine\":" << line << ",";
  out << "\"startColumn\":" << column << ",";
  out << "\"endLine\":0,";
  out << "\"endColumn\":0";
  out << "}}";
  pushDebugEvent(runtime, out.str());
}

void emitNewScripts(ExactHermesRuntime* runtime,
                    facebook::hermes::debugger::Debugger& debugger) {
  if (!runtime || !runtime->runtime) {
    return;
  }
  auto scripts = debugger.getLoadedScripts();
  for (const auto& script : scripts) {
    if (runtime->known_scripts.insert(script.fileId).second) {
      runtime->script_id_to_name[script.fileId] = script.fileName;
      emitScriptParsed(runtime, script);
    }
  }
}

template <typename F>
std::string runOnRuntimeThread(ExactHermesRuntime* runtime, F func) {
  if (!runtime) {
    return std::string();
  }

  auto safe_call = [runtime, &func]() -> std::string {
    try {
      return func(runtime);
    } catch (const facebook::jsi::JSError& err) {
      ex_host_console_log(1, err.getMessage().c_str());
      return std::string();
    } catch (const std::exception& err) {
      ex_host_console_log(1, err.what());
      return std::string();
    } catch (...) {
      ex_host_console_log(1, "Unknown native error");
      return std::string();
    }
  };

  auto debugger_snapshot = snapshotDebugger(runtime);
  if (!debugger_snapshot) {
    return std::string();
  }

  if (std::this_thread::get_id() == runtime->runtime_thread) {
    return safe_call();
  }
  if (!runtime->debugger_available.load()) {
    return std::string();
  }

  auto promise = std::make_shared<std::promise<std::string>>();
  auto future = promise->get_future();
  try {
    debugger_snapshot->triggerInterrupt_TS(
        [promise, safe_call](facebook::hermes::HermesRuntime&) mutable {
          promise->set_value(safe_call());
        });
  } catch (const facebook::jsi::JSError& err) {
    ex_host_console_log(1, err.getMessage().c_str());
    return std::string();
  } catch (const std::exception& err) {
    ex_host_console_log(1, err.what());
    return std::string();
  } catch (...) {
    ex_host_console_log(1, "Unknown native error");
    return std::string();
  }
  return future.get();
}

template <typename F>
std::string withDebuggerOnRuntimeThread(ExactHermesRuntime* runtime, F func) {
  auto debugger_snapshot = snapshotDebugger(runtime);
  if (!runtime || !runtime->runtime || !debugger_snapshot) {
    return std::string();
  }

  auto safe_call = [runtime, debugger_snapshot, &func]() -> std::string {
    try {
      return func(runtime, runtime->runtime->getDebugger());
    } catch (const facebook::jsi::JSError& err) {
      ex_host_console_log(1, err.getMessage().c_str());
      return std::string();
    } catch (const std::exception& err) {
      ex_host_console_log(1, err.what());
      return std::string();
    } catch (...) {
      ex_host_console_log(1, "Unknown native error");
      return std::string();
    }
  };

  if (std::this_thread::get_id() == runtime->runtime_thread) {
    return safe_call();
  }
  if (!runtime->debugger_available.load()) {
    return std::string();
  }

  auto promise = std::make_shared<std::promise<std::string>>();
  auto future = promise->get_future();
  try {
    debugger_snapshot->triggerInterrupt_TS(
        [promise, safe_call](facebook::hermes::HermesRuntime&) mutable {
          promise->set_value(safe_call());
        });
  } catch (const facebook::jsi::JSError& err) {
    ex_host_console_log(1, err.getMessage().c_str());
    return std::string();
  } catch (const std::exception& err) {
    ex_host_console_log(1, err.what());
    return std::string();
  } catch (...) {
    ex_host_console_log(1, "Unknown native error");
    return std::string();
  }

  return future.get();
}

// Cached at first use; -1 = uninitialized
static int g_allow_all = -1;
static thread_local uint64_t g_active_module_id = 0;

bool isAllowAll() {
  if (g_allow_all < 0) {
    g_allow_all = ex_host_is_allow_all();
  }
  return g_allow_all != 0;
}

bool checkCapability(const std::string& capability) {
  if (isAllowAll()) {
    return true;
  }
  auto allowed = ex_host_check_capability(g_active_module_id, capability.c_str());
  ex_host_log_event(
      allowed ? "capability_granted" : "capability_denied",
      g_active_module_id,
      capability.c_str(),
      allowed);
  return allowed != 0;
}

std::string getEnvValue(const std::string& key) {
  char buffer[4096];
  auto written = ex_host_env_get(key.c_str(), buffer, sizeof(buffer));
  if (written == 0) {
    return std::string();
  }
  return std::string(buffer, buffer + written);
}

facebook::jsi::Value makeUint8Array(facebook::jsi::Runtime& rt, std::vector<uint8_t> data) {
  auto buffer = std::make_shared<VectorBuffer>(std::move(data));
  facebook::jsi::ArrayBuffer arrayBuffer(rt, buffer);
  auto ctor = rt.global().getPropertyAsFunction(rt, "Uint8Array");
  auto typed = ctor.callAsConstructor(rt, arrayBuffer).getObject(rt);
  return facebook::jsi::Value(std::move(typed));
}

static bool sqliteColumnTypeIsBlob(
    facebook::jsi::Runtime& runtime,
    const facebook::jsi::Array& columnTypes,
    size_t index) {
  auto type = columnTypes.getValueAtIndex(runtime, index);
  return type.isString() && type.asString(runtime).utf8(runtime) == "BLOB";
}

static facebook::jsi::Value convertSqliteBlobValue(
    facebook::jsi::Runtime& runtime,
    facebook::jsi::Value value) {
  if (!value.isObject()) {
    return value;
  }

  auto object = value.asObject(runtime);
  if (!object.isArray(runtime)) {
    return value;
  }

  auto array = object.asArray(runtime);
  auto length = array.size(runtime);
  std::vector<uint8_t> bytes;
  bytes.reserve(length);
  for (size_t i = 0; i < length; ++i) {
    auto entry = array.getValueAtIndex(runtime, i);
    if (!entry.isNumber()) {
      return value;
    }
    auto number = entry.asNumber();
    if (number < 0 || number > 255) {
      return value;
    }
    bytes.push_back(static_cast<uint8_t>(number));
  }

  return makeUint8Array(runtime, std::move(bytes));
}

static void convertSqliteBlobColumnsInRowObject(
    facebook::jsi::Runtime& runtime,
    facebook::jsi::Object& row,
    const facebook::jsi::Array& columnTypes) {
  auto keys = row.getPropertyNames(runtime);
  auto limit = std::min(keys.size(runtime), columnTypes.size(runtime));
  for (size_t i = 0; i < limit; ++i) {
    if (!sqliteColumnTypeIsBlob(runtime, columnTypes, i)) {
      continue;
    }
    auto key = keys.getValueAtIndex(runtime, i);
    if (!key.isString()) {
      continue;
    }
    auto property = key.asString(runtime).utf8(runtime);
    row.setProperty(
        runtime,
        property.c_str(),
        convertSqliteBlobValue(runtime, row.getProperty(runtime, property.c_str())));
  }
}

static void convertSqliteBlobColumnsInRowArray(
    facebook::jsi::Runtime& runtime,
    facebook::jsi::Array& row,
    const facebook::jsi::Array& columnTypes) {
  auto limit = std::min(row.size(runtime), columnTypes.size(runtime));
  for (size_t i = 0; i < limit; ++i) {
    if (!sqliteColumnTypeIsBlob(runtime, columnTypes, i)) {
      continue;
    }
    row.setValueAtIndex(
        runtime,
        i,
        convertSqliteBlobValue(runtime, row.getValueAtIndex(runtime, i)));
  }
}

static void convertSqliteBlobColumns(
    facebook::jsi::Runtime& runtime,
    facebook::jsi::Object& result) {
  auto columnTypesValue = result.getProperty(runtime, "columnTypes");
  if (!columnTypesValue.isObject()) {
    return;
  }

  auto columnTypesObject = columnTypesValue.asObject(runtime);
  if (!columnTypesObject.isArray(runtime)) {
    return;
  }

  auto columnTypes = columnTypesObject.asArray(runtime);

  auto rowValue = result.getProperty(runtime, "row");
  if (rowValue.isObject()) {
    auto rowObject = rowValue.asObject(runtime);
    if (rowObject.isArray(runtime)) {
      auto rowArray = rowObject.asArray(runtime);
      convertSqliteBlobColumnsInRowArray(runtime, rowArray, columnTypes);
      result.setProperty(runtime, "row", rowArray);
    } else {
      convertSqliteBlobColumnsInRowObject(runtime, rowObject, columnTypes);
      result.setProperty(runtime, "row", rowObject);
    }
  }

  auto rowsValue = result.getProperty(runtime, "rows");
  if (!rowsValue.isObject()) {
    return;
  }

  auto rowsObject = rowsValue.asObject(runtime);
  if (!rowsObject.isArray(runtime)) {
    return;
  }

  auto rows = rowsObject.asArray(runtime);
  auto rowCount = rows.size(runtime);
  for (size_t i = 0; i < rowCount; ++i) {
    auto rowValue = rows.getValueAtIndex(runtime, i);
    if (!rowValue.isObject()) {
      continue;
    }

    auto rowObject = rowValue.asObject(runtime);
    if (rowObject.isArray(runtime)) {
      auto rowArray = rowObject.asArray(runtime);
      convertSqliteBlobColumnsInRowArray(runtime, rowArray, columnTypes);
      rows.setValueAtIndex(runtime, i, rowArray);
    } else {
      convertSqliteBlobColumnsInRowObject(runtime, rowObject, columnTypes);
      rows.setValueAtIndex(runtime, i, rowObject);
    }
  }

  result.setProperty(runtime, "rows", rows);
}

// Extract bytes from a JSI value (string, ArrayBuffer, or TypedArray like Uint8Array)
std::vector<uint8_t> extractBytes(facebook::jsi::Runtime& rt, const facebook::jsi::Value& val) {
  if (val.isString()) {
    auto str = val.asString(rt).utf8(rt);
    return std::vector<uint8_t>(str.begin(), str.end());
  }
  if (val.isObject()) {
    auto obj = val.asObject(rt);
    if (obj.isArrayBuffer(rt)) {
      auto buf = obj.getArrayBuffer(rt);
      return std::vector<uint8_t>(buf.data(rt), buf.data(rt) + buf.size(rt));
    }
    // TypedArray (Uint8Array, etc.) — get the underlying buffer, byteOffset, byteLength
    if (obj.hasProperty(rt, "buffer")) {
      auto bufProp = obj.getProperty(rt, "buffer");
      if (bufProp.isObject()) {
        auto bufObj = bufProp.asObject(rt);
        if (bufObj.isArrayBuffer(rt)) {
          auto ab = bufObj.getArrayBuffer(rt);
          size_t offset = 0;
          size_t length = ab.size(rt);
          auto offProp = obj.getProperty(rt, "byteOffset");
          if (offProp.isNumber()) offset = static_cast<size_t>(offProp.asNumber());
          auto lenProp = obj.getProperty(rt, "byteLength");
          if (lenProp.isNumber()) length = static_cast<size_t>(lenProp.asNumber());
          auto* ptr = ab.data(rt) + offset;
          return std::vector<uint8_t>(ptr, ptr + length);
        }
      }
    }
    // Fallback: try to read .length and index
    if (obj.hasProperty(rt, "length")) {
      auto lenVal = obj.getProperty(rt, "length");
      if (lenVal.isNumber()) {
        size_t len = static_cast<size_t>(lenVal.asNumber());
        std::vector<uint8_t> result(len);
        for (size_t i = 0; i < len; i++) {
          auto v = obj.getPropertyAsObject(rt, "0"); // won't work for indexed
          // Use bracket notation via asArray
          break; // fallback won't work well, use above methods
        }
      }
    }
  }
  return {};
}

struct IoVecMetadata {
  bool isArrayBuffer;
  size_t byteOffset;
  size_t byteLength;
};

static bool parseIoVecArguments(
    facebook::jsi::Runtime& runtime,
    const facebook::jsi::Value& value,
    std::vector<std::vector<uint8_t>>& buffers,
    std::vector<struct iovec>& iovecs,
    std::vector<IoVecMetadata>* metadata) {
  if (!value.isObject()) {
    return false;
  }
  auto listObj = value.asObject(runtime);
  if (!listObj.isArray(runtime)) {
    return false;
  }
  auto lengthValue = listObj.getProperty(runtime, "length");
  if (!lengthValue.isNumber()) {
    return false;
  }
  auto length = static_cast<size_t>(lengthValue.asNumber());
  buffers.reserve(length);
  iovecs.reserve(length);
  if (metadata) {
    metadata->reserve(length);
  }
  for (size_t i = 0; i < length; i++) {
    std::string index = std::to_string(i);
    auto entry = listObj.getProperty(runtime, facebook::jsi::PropNameID::forAscii(runtime, index));
    if (!entry.isObject()) {
      return false;
    }
    auto entryObj = entry.asObject(runtime);
    size_t byteOffset = 0;
    size_t byteLength = 0;
    const uint8_t* source = nullptr;
    bool isArrayBuffer = false;
    if (entryObj.isArrayBuffer(runtime)) {
      auto ab = entryObj.getArrayBuffer(runtime);
      source = ab.data(runtime);
      byteLength = ab.size(runtime);
      isArrayBuffer = true;
    } else if (entryObj.hasProperty(runtime, "buffer")) {
      auto bufferValue = entryObj.getProperty(runtime, "buffer");
      if (!bufferValue.isObject()) {
        return false;
      }
      auto bufferObj = bufferValue.asObject(runtime);
      if (!bufferObj.isArrayBuffer(runtime)) {
        return false;
      }
      auto ab = bufferObj.getArrayBuffer(runtime);
      size_t available = ab.size(runtime);
      byteOffset = entryObj.hasProperty(runtime, "byteOffset")
          ? static_cast<size_t>(entryObj.getProperty(runtime, "byteOffset").asNumber())
          : 0;
      byteLength = entryObj.hasProperty(runtime, "byteLength")
          ? static_cast<size_t>(entryObj.getProperty(runtime, "byteLength").asNumber())
          : (available - byteOffset);
      if (byteOffset > available) {
        return false;
      }
      if (byteOffset + byteLength > available) {
        byteLength = available - byteOffset;
      }
      source = ab.data(runtime) + byteOffset;
    } else {
      return false;
    }
    if (byteLength > 0 && !source) {
      return false;
    }
    auto bytes = source ? std::vector<uint8_t>(source, source + byteLength) : std::vector<uint8_t>();
    buffers.push_back(std::move(bytes));
    auto& bytesRef = buffers.back();
    struct iovec iov {
      .iov_base = bytesRef.empty() ? nullptr : bytesRef.data(),
      .iov_len = bytesRef.size()
    };
    iovecs.push_back(iov);
    if (metadata) {
      metadata->push_back({isArrayBuffer, byteOffset, byteLength});
    }
  }
  return true;
}

#if defined(__APPLE__)
static std::string normalizeHashForNodeCrypto(const std::string& algorithm) {
  auto lowered = algorithm;
  for (auto& ch : lowered) {
    ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
  }

  if (lowered == "ecdsa" || lowered == "ecdsa-with-sha1") return "sha1";
  if (lowered == "ecdsa-with-sha256" || lowered == "rsa-sha256" || lowered == "sha256") return "sha256";
  if (lowered == "ecdsa-with-sha384" || lowered == "rsa-sha384" || lowered == "sha384") return "sha384";
  if (lowered == "ecdsa-with-sha512" || lowered == "rsa-sha512" || lowered == "sha512") return "sha512";
  if (lowered.find("sha1") != std::string::npos) return "sha1";
  if (lowered.find("sha256") != std::string::npos) return "sha256";
  if (lowered.find("sha384") != std::string::npos) return "sha384";
  if (lowered.find("sha512") != std::string::npos) return "sha512";
  if (lowered.find("md5") != std::string::npos) return "md5";
  return "sha256";
}

static SecKeyAlgorithm pickSecKeySignAlgorithm(const std::string& hashName, bool isRsa) {
  if (isRsa) {
    if (hashName == "sha1") return kSecKeyAlgorithmRSASignatureMessagePKCS1v15SHA1;
    if (hashName == "sha256") return kSecKeyAlgorithmRSASignatureMessagePKCS1v15SHA256;
    if (hashName == "sha384") return kSecKeyAlgorithmRSASignatureMessagePKCS1v15SHA384;
    if (hashName == "sha512") return kSecKeyAlgorithmRSASignatureMessagePKCS1v15SHA512;
    return nullptr;
  }

  if (hashName == "sha1") return kSecKeyAlgorithmECDSASignatureMessageX962SHA1;
  if (hashName == "sha256") return kSecKeyAlgorithmECDSASignatureMessageX962SHA256;
  if (hashName == "sha384") return kSecKeyAlgorithmECDSASignatureMessageX962SHA384;
  if (hashName == "sha512") return kSecKeyAlgorithmECDSASignatureMessageX962SHA512;
  return nullptr;
}

static bool isRsaSecKey(SecKeyRef key) {
  bool isRsa = false;
  CFUniquePtr attrs(static_cast<const void*>(SecKeyCopyAttributes(key)));
  if (attrs.get()) {
    auto type = CFDictionaryGetValue(
        static_cast<CFDictionaryRef>(attrs.get()), kSecAttrKeyType);
    if (type != nullptr) {
      isRsa = CFEqual(type, kSecAttrKeyTypeRSA);
    }
  }
  return isRsa;
}

static std::string dataToString(CFDataRef data) {
  if (!data) return {};
  const auto bytes = CFDataGetBytePtr(data);
  const auto len = CFDataGetLength(data);
  return std::string(reinterpret_cast<const char*>(bytes), static_cast<size_t>(len));
}

#if !defined(EXACT_PLATFORM_IOS)
// SecItemImport/SecItemExport are macOS-only APIs (not available on iOS)
static SecKeyRef importPemKey(const std::string& pemText, SecExternalItemType itemType) {
  auto keyBytes = std::vector<uint8_t>(pemText.begin(), pemText.end());
  CFUniquePtr keyData(static_cast<const void*>(CFDataCreate(
      kCFAllocatorDefault,
      keyBytes.data(),
      static_cast<CFIndex>(keyBytes.size()))));
  if (!keyData) {
    return nullptr;
  }

  SecItemImportExportKeyParameters keyParams{};
  keyParams.version = SEC_KEY_IMPORT_EXPORT_PARAMS_VERSION;

  CFArrayRef importedItems = nullptr;
  SecExternalFormat inputFormat = kSecFormatPEMSequence;
  SecExternalItemType effectiveType = itemType;
  auto status = SecItemImport(
      static_cast<CFDataRef>(keyData.get()),
      nullptr,
      &inputFormat,
      &effectiveType,
      0,
      &keyParams,
      nullptr,
      &importedItems);
  CFUniquePtr importedItemsHandle(static_cast<const void*>(importedItems));

  if (status != noErr) {
    if (status != noErr && itemType != kSecItemTypeUnknown) {
      effectiveType = kSecItemTypeUnknown;
      importedItemsHandle.reset();
      importedItems = nullptr;
      status = SecItemImport(
          static_cast<CFDataRef>(keyData.get()),
          nullptr,
          &inputFormat,
          &effectiveType,
          0,
          &keyParams,
          nullptr,
          &importedItems);
      importedItemsHandle.reset(static_cast<const void*>(importedItems));
    }
  }

  if (status != noErr || !importedItems) {
    return nullptr;
  }

  auto importedItemsArray = static_cast<CFArrayRef>(importedItemsHandle.get());
  if (CFArrayGetCount(importedItemsArray) == 0) {
    return nullptr;
  }

  auto maybeKey = CFArrayGetValueAtIndex(importedItemsArray, 0);
  if (!maybeKey) {
    return nullptr;
  }

  if (CFGetTypeID(maybeKey) != SecKeyGetTypeID()) {
    return nullptr;
  }

  auto key = static_cast<SecKeyRef>(const_cast<void*>(maybeKey));
  CFRetain(key);
  return key;
}
#endif // !EXACT_PLATFORM_IOS
#endif // __APPLE__

// These helpers are only used by the non-Apple (Linux/OpenSSL) sign/verify path.
// On Apple, sign/verify uses Security.framework directly.
#if !defined(__APPLE__) && !defined(EXACT_NO_OPENSSL)
static const EVP_MD* selectDigestForCryptoAlgo(const std::string& algorithm) {
  if (algorithm == "sha1" || algorithm == "sha-1") return EVP_sha1();
  if (algorithm == "sha256" || algorithm == "sha-256") return EVP_sha256();
  if (algorithm == "sha384" || algorithm == "sha-384") return EVP_sha384();
  if (algorithm == "sha512" || algorithm == "sha-512") return EVP_sha512();
  if (algorithm == "md5" || algorithm == "md5") return EVP_md5();
  return nullptr;
}

static std::string digestAlgorithmFromNodeCrypto(const std::string& algorithm) {
  auto lowered = algorithm;
  for (auto& ch : lowered) {
    ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
  }

  if (lowered == "ecdsa" || lowered == "ecdsa-with-sha1") return "sha1";
  if (lowered == "ecdsa-with-sha256" || lowered == "rsa-sha256" || lowered == "sha256") return "sha256";
  if (lowered == "ecdsa-with-sha384" || lowered == "rsa-sha384" || lowered == "sha384") return "sha384";
  if (lowered == "ecdsa-with-sha512" || lowered == "rsa-sha512" || lowered == "sha512") return "sha512";
  if (lowered.find("sha1") != std::string::npos) return "sha1";
  if (lowered.find("sha256") != std::string::npos) return "sha256";
  if (lowered.find("sha384") != std::string::npos) return "sha384";
  if (lowered.find("sha512") != std::string::npos) return "sha512";
  if (lowered.find("md5") != std::string::npos) return "md5";
  return "sha256";
}
#endif

