            std::lock_guard<std::mutex> lock(g_tcp_mutex);
            auto it = g_tcp_sockets.find(handle);
            if (it == g_tcp_sockets.end()) throw facebook::jsi::JSError(runtime, "__exactTcpWrite: invalid handle");
