        const EVP_MD* md = nullptr;
        if (algo == "sha256" || algo == "sha-256") md = EVP_sha256();
        else if (algo == "sha1" || algo == "sha-1") md = EVP_sha1();
        else if (algo == "sha384" || algo == "sha-384") md = EVP_sha384();
