        facebook::jsi::Object result(runtime);
        result.setProperty(runtime, "keyType", facebook::jsi::String::createFromUtf8(runtime, keyTypeStr));
        result.setProperty(runtime, "rawKeyData", makeUint8Array(runtime, std::move(rawKey)));
